/**
 * Hero poster content. Everything on the end frame is sourced from here so
 * copy edits never touch the layout.
 */
export type HalftoneMode = 'thermal' | 'mono'

/**
 * `thermal`: every dot keeps its source pixel colour (orange -> magenta -> violet).
 * `mono`:    ink-coloured dots only.
 * Both files are generated by `scripts/hero/halftone.mjs`.
 */
export const HALFTONE_MODE: HalftoneMode = 'thermal'

export const HALFTONE_SRC: Record<HalftoneMode, string> = {
  thermal: '/hero/portrait-halftone.webp',
  mono: '/hero/portrait-halftone-mono.webp',
}

export const SOCIAL = {
  github: 'https://github.com/sameermotwani17-cell',
  linkedin: 'https://www.linkedin.com/in/sameer-motwani-2625a62b5/',
  instagram: 'https://www.instagram.com/retro.studios_',
  tiktok: 'https://www.tiktok.com/@retro.studios',
} as const

