/**
 * 3x3 tile fill pattern, row-major. `filled` shows a slice of the halftone,
 * `empty` shows paper, `statement` holds the red statement block.
 * The stack's middle row overlaps the empty cell at row 2, column 1.
 */
export const TILE_PATTERN = [
  ['filled', 'filled', 'empty'],
  ['empty', 'filled', 'filled'],
  ['filled', 'filled', 'statement'],
] as const

export type TileKind = (typeof TILE_PATTERN)[number][number]
